-- Changelog-item: servicedesk krijgt een apart bord voor mutatie en dagelijks onderhoud.
insert into public.changelog (datum, categorie, module, titel, omschrijving) values
  ('2026-09-11','nieuw','Servicedesk','Mutatie en dagelijks onderhoud hebben nu een eigen bord',
   'Bovenaan de servicedesk staat een knop waarmee je wisselt tussen Dagelijks onderhoud en Mutatie. Die twee doorlopen een heel ander traject, en daarom heeft elk nu zijn eigen kolommen. Dagelijks onderhoud blijft zoals je gewend was. Mutatie loopt van Nieuw via Opgenomen, Offerte verstuurd, In voorbereiding, Onderhanden en Uitvoering gereed naar Kosten compleet en Financieel gereed. Achter elke knop staat hoeveel dossiers er aan die kant staan, en de app onthoudt waar je het laatst stond. Rond je een opname af op een mutatiedossier, dan schuift de kaart vanzelf door naar Opgenomen. Mutatiewerk staat voortaan standaard op Aangenomen in plaats van Regie; je kunt dat per dossier nog steeds zelf omzetten.');
